        do { knt++; for(int i=0;i<n-1;i++) x[i*incx]*=rsafmn; beta*=rsafmn; *alpha*=rsafmn; } while(fabs(beta)<safmn && knt<20);
        sc=0; ss=1;
        for (int i=0;i<n-1;i++){ double v=x[i*incx]; if(v!=0){double a=fabs(v); if(sc<a){ss=1+ss*(sc/a)*(sc/a);sc=a;} else ss+=(a/sc)*(a/sc);} }
        xn = sc*sqrt(ss);
        beta = -sgn(lapy2(*alpha, xn), *alpha);
    }
    *tau = (beta - *alpha)/beta;
    double s = 1/(*alpha - beta);
    for (int i=0;i<n-1;i++) x[i*incx]*=s;
    for (int j=0;j<knt;j++) beta*=safmn;
    *alpha = beta;
}

void my_dlarf(const char* side, const int* M, const int* N, const double* v, const int* incv,
              const double* tau, double* c, const int* ldc, double* work){
    int m=*M, n=*N, ld=*ldc, iv=*incv; double t=*tau;
    if (t == 0) return;
    if (iv < 0) iv = -iv; /* only used with incv=1 in ARPACK; abs safe for symmetric use? keep */
    if (*side=='L' || *side=='l'){
        for (int j=0;j<n;j++){
            double* cj=c+(long)j*ld; double s=0;
            for (int i=0;i<m;i++) s+=cj[i]*v[i*iv];
            s*=t;
            for (int i=0;i<m;i++) cj[i]-=s*v[i*iv];
        }
    } else {
        for (int i=0;i<m;i++){
            double s=0;
            for (int j=0;j<n;j++) s+=c[i+(long)j*ld]*v[j*iv];
            s*=t;
            for (int j=0;j<n;j++) c[i+(long)j*ld]-=s*v[j*iv];
        }
    }
}

static void dlanv2(double* a, double* b, double* c, double* d, double* rt1r, double* rt1i,
                   double* rt2r, double* rt2i, double* cs, double* sn){
    const double eps = ULP;
    double safmn2 = pow(2.0, (int)(log(SAFMIN/eps)/log(2.0)/2.0));
    double safmx2 = 1/safmn2;
    if (*c == 0){ *cs=1; *sn=0; }
    else if (*b == 0){ *cs=0; *sn=1; double tmp=*d; *d=*a; *a=tmp; *b=-*c; *c=0; }
    else if ((*a-*d)==0 && sgn(1,*b)!=sgn(1,*c)){ *cs=1; *sn=0; }
    else {
        double temp=*a-*d, p=0.5*temp;
        double bcmax=fmax(fabs(*b),fabs(*c));
        double bcmis=fmin(fabs(*b),fabs(*c))*sgn(1,*b)*sgn(1,*c);
        double scale=fmax(fabs(p),bcmax);
        double zz=(p/scale)*p+(bcmax/scale)*bcmis;
        if (zz >= 4*eps){
            zz = p + sgn(sqrt(scale)*sqrt(zz), p);
            *a = *d + zz;
            *d = *d - (bcmax/zz)*bcmis;
            double tau=lapy2(*c,zz);
            *cs=zz/tau; *sn=*c/tau; *b=*b-*c; *c=0;
        } else {
            int count=0; double sigma=*b+*c;
            for(;;){
                count++;
                scale=fmax(fabs(temp),fabs(sigma));
                if (scale>=safmx2){ sigma*=safmn2; temp*=safmn2; if(count<=20) continue; }
                if (scale<=safmn2){ sigma*=safmx2; temp*=safmx2; if(count<=20) continue; }
                break;
            }
            p=0.5*temp;
            double tau=lapy2(sigma,temp);
            *cs=sqrt(0.5*(1+fabs(sigma)/tau));
            *sn=-(p/(tau* *cs))*sgn(1,sigma);
            double aa=*a* *cs+*b* *sn, bb=-*a* *sn+*b* *cs, cc=*c* *cs+*d* *sn, dd=-*c* *sn+*d* *cs;
            *a=aa* *cs+cc* *sn; *b=bb* *cs+dd* *sn; *c=-aa* *sn+cc* *cs; *d=-bb* *sn+dd* *cs;
            temp=0.5*(*a+*d); *a=temp; *d=temp;
            if (*c!=0){
                if (*b!=0){
                    if (sgn(1,*b)==sgn(1,*c)){
                        double sab=sqrt(fabs(*b)), sac=sqrt(fabs(*c));
                        p=sgn(sab*sac,*c);
                        tau=1/sqrt(fabs(*b+*c));
                        *a=temp+p; *d=temp-p; *b=*b-*c; *c=0;
                        double cs1=sab*tau, sn1=sac*tau;
                        temp=*cs*cs1-*sn*sn1; *sn=*cs*sn1+*sn*cs1; *cs=temp;
                    }
                } else { *b=-*c; *c=0; temp=*cs; *cs=-*sn; *sn=temp; }
            }
        }
    }
    *rt1r=*a; *rt2r=*d;
    if (*c==0){ *rt1i=0; *rt2i=0; }
    else { *rt1i=sqrt(fabs(*b))*sqrt(fabs(*c)); *rt2i=-*rt1i; }
}

static void drot(int n, double* x, int incx, double* y, int incy, double c, double s){
    for (int i=0;i<n;i++){ double a=x[i*incx], b=y[i*incy]; x[i*incx]=c*a+s*b; y[i*incy]=c*b-s*a; }
}

void my_dlahqr(const int* WANTT, const int* WANTZ, const int* N, const int* ILO, const int* IHI,
               double* h, const int* LDH, double* wr, double* wi, const int* ILOZ, const int* IHIZ,
               double* z, const int* LDZ, int* info){
    int wantt=*WANTT, wantz=*WANTZ, n=*N, ilo=*ILO, ihi=*IHI, ldh=*LDH, iloz=*ILOZ, ihiz=*IHIZ, ldz=*LDZ;
    const double dat1=0.75, dat2=-0.4375; const int kexsh=10;
    *info=0;
    if (n==0) return;
    if (ilo==ihi){ wr[ilo-1]=H_(ilo,ilo); wi[ilo-1]=0; return; }
    for (int j=ilo;j<=ihi-3;j++){ H_(j+2,j)=0; H_(j+3,j)=0; }
    if (ilo<=ihi-2) H_(ihi,ihi-2)=0;
    int nh=ihi-ilo+1, nz=ihiz-iloz+1;
    double smlnum=SAFMIN*((double)nh/ULP);
    int i1=1,i2=n;
    if (wantt){ i1=1; i2=n; }
    int itmax=30*(nh>10?nh:10);
    int kdefl=0;
    int i=ihi;
    double v[3];
    while (i >= ilo){
        int l=ilo, converged=0;
        for (int its=0; its<=itmax; its++){
            int k;
            for (k=i;k>=l+1;k--){
                if (fabs(H_(k,k-1))<=smlnum) break;
                double tst=fabs(H_(k-1,k-1))+fabs(H_(k,k));
                if (tst==0){
                    if (k-2>=ilo) tst+=fabs(H_(k-1,k-2));
                    if (k+1<=ihi) tst+=fabs(H_(k+1,k));
                }
                if (fabs(H_(k,k-1))<=ULP*tst){
                    double ab=fmax(fabs(H_(k,k-1)),fabs(H_(k-1,k)));
                    double ba=fmin(fabs(H_(k,k-1)),fabs(H_(k-1,k)));
                    double aa=fmax(fabs(H_(k,k)),fabs(H_(k-1,k-1)-H_(k,k)));
                    double bb=fmin(fabs(H_(k,k)),fabs(H_(k-1,k-1)-H_(k,k)));
                    double s=aa+ab;
                    if (ba*(ab/s)<=fmax(smlnum,ULP*(bb*(aa/s)))) break;
                }
            }
            l=k;
            if (l>ilo) H_(l,l-1)=0;
            if (l>=i-1){ converged=1; break; }
            kdefl++;
            if (!wantt){ i1=l; i2=i; }
            double h11,h12,h21,h22,s;
            if (kdefl%(2*kexsh)==0){
                s=fabs(H_(i,i-1))+fabs(H_(i-1,i-2));
                h11=dat1*s+H_(i,i); h12=dat2*s; h21=s; h22=h11;
            } else if (kdefl%kexsh==0){
                s=fabs(H_(l+1,l))+fabs(H_(l+2,l+1));
                h11=dat1*s+H_(l,l); h12=dat2*s; h21=s; h22=h11;
            } else {
                h11=H_(i-1,i-1); h21=H_(i,i-1); h12=H_(i-1,i); h22=H_(i,i);
            }
            s=fabs(h11)+fabs(h12)+fabs(h21)+fabs(h22);
            double rt1r,rt1i,rt2r,rt2i;
            if (s==0){ rt1r=rt1i=rt2r=rt2i=0; }
            else {
                h11/=s; h21/=s; h12/=s; h22/=s;
                double tr=(h11+h22)/2;
                double det=(h11-tr)*(h22-tr)-h12*h21;
                double rtdisc=sqrt(fabs(det));
                if (det>=0){ rt1r=tr*s; rt2r=rt1r; rt1i=rtdisc*s; rt2i=-rt1i; }
                else {
                    rt1r=tr+rtdisc; rt2r=tr-rtdisc;
                    if (fabs(rt1r-h22)<=fabs(rt2r-h22)){ rt1r*=s; rt2r=rt1r; }
                    else { rt2r*=s; rt1r=rt2r; }
                    rt1i=rt2i=0;
                }
            }
            int m;
            for (m=i-2;m>=l;m--){
                double h21s=H_(m+1,m);
                s=fabs(H_(m,m)-rt2r)+fabs(rt2i)+fabs(h21s);
                h21s=H_(m+1,m)/s;
                v[0]=h21s*H_(m,m+1)+(H_(m,m)-rt1r)*((H_(m,m)-rt2r)/s)-rt1i*(rt2i/s);
                v[1]=h21s*(H_(m,m)+H_(m+1,m+1)-rt1r-rt2r);
                v[2]=h21s*H_(m+2,m+1);
                s=fabs(v[0])+fabs(v[1])+fabs(v[2]);
                v[0]/=s; v[1]/=s; v[2]/=s;
                if (m==l) break;
                double h00=fabs(H_(m,m-1))*(fabs(v[1])+fabs(v[2]));
                double h01=fabs(v[0])*(fabs(H_(m-1,m-1))+fabs(H_(m,m))+fabs(H_(m+1,m+1)));
                if (h00<=ULP*h01) break;
            }
            for (int k2=m;k2<=i-1;k2++){
                int nr=3<(i-k2+1)?3:(i-k2+1);
                if (k2>m){ for(int q=0;q<nr;q++) v[q]=H_(k2+q,k2-1); }
                double t1;
                my_dlarfg(nr,&v[0],&v[1],1,&t1);
                if (k2>m){
                    H_(k2,k2-1)=v[0]; H_(k2+1,k2-1)=0;
                    if (k2<i-1) H_(k2+2,k2-1)=0;
                } else if (m>l){
                    H_(k2,k2-1)=H_(k2,k2-1)*(1-t1);
                }
                double v2=v[1], t2=t1*v2;
                if (nr==3){
                    double v3=v[2], t3=t1*v3;
                    for (int j=k2;j<=i2;j++){
                        double sum=H_(k2,j)+v2*H_(k2+1,j)+v3*H_(k2+2,j);
                        H_(k2,j)-=sum*t1; H_(k2+1,j)-=sum*t2; H_(k2+2,j)-=sum*t3;
                    }
                    int jm = (k2+3<i)?k2+3:i;
                    for (int j=i1;j<=jm;j++){
                        double sum=H_(j,k2)+v2*H_(j,k2+1)+v3*H_(j,k2+2);
                        H_(j,k2)-=sum*t1; H_(j,k2+1)-=sum*t2; H_(j,k2+2)-=sum*t3;
                    }
                    if (wantz) for (int j=iloz;j<=ihiz;j++){
                        double sum=Z_(j,k2)+v2*Z_(j,k2+1)+v3*Z_(j,k2+2);
                        Z_(j,k2)-=sum*t1; Z_(j,k2+1)-=sum*t2; Z_(j,k2+2)-=sum*t3;
                    }
                } else if (nr==2){
                    for (int j=k2;j<=i2;j++){
                        double sum=H_(k2,j)+v2*H_(k2+1,j);
                        H_(k2,j)-=sum*t1; H_(k2+1,j)-=sum*t2;
                    }
                    for (int j=i1;j<=i;j++){
                        double sum=H_(j,k2)+v2*H_(j,k2+1);
                        H_(j,k2)-=sum*t1; H_(j,k2+1)-=sum*t2;
                    }
                    if (wantz) for (int j=iloz;j<=ihiz;j++){
                        double sum=Z_(j,k2)+v2*Z_(j,k2+1);
                        Z_(j,k2)-=sum*t1; Z_(j,k2+1)-=sum*t2;
                    }
                }
            }
        }
        if (!converged){ *info=i; return; }
        if (l==i){ wr[i-1]=H_(i,i); wi[i-1]=0; }
        else if (l==i-1){
            double cs,sn;
            dlanv2(&H_(i-1,i-1),&H_(i-1,i),&H_(i,i-1),&H_(i,i),&wr[i-2],&wi[i-2],&wr[i-1],&wi[i-1],&cs,&sn);
            if (wantt){
                if (i2>i) drot(i2-i,&H_(i-1,i+1),ldh,&H_(i,i+1),ldh,cs,sn);
                drot(i-i1-1,&H_(i1,i-1),1,&H_(i1,i),1,cs,sn);
            }
            if (wantz) drot(nz,&Z_(iloz,i-1),1,&Z_(iloz,i),1,cs,sn);
        }
        kdefl=0;
        i=l-1;
    }
}

typedef void (*trevc_t)(const char*,const char*,int*,const int*,const double*,const int*,double*,const int*,
                        double*,const int*,const int*,int*,double*,int*,long,long);
void* orig_trevc = 0;

/* complex 2x2 solve: (A - lam I) x = b, A real 2x2, lam=wr+i wi */
void my_dtrevc(const char* side, const char* howmny, int* select, const int* N, const double* t, const int* LDT,
               double* vl, const int* LDVL, double* vr, const int* LDVR, const int* MM, int* M,
               double* work, int* info, long l1, long l2){
    if (!((*side=='R'||*side=='r') && (*howmny=='A'||*howmny=='a'))){
        ((trevc_t)orig_trevc)(side,howmny,select,N,t,LDT,vl,LDVL,vr,LDVR,MM,M,work,info,l1,l2);
        return;
    }
    int n=*N, ldt=*LDT, ldv=*LDVR;
    *info=0; *M=n;
    #define T_(i,j) t[((i)-1)+((j)-1)*(long)ldt]
    #define V_(i,j) vr[((i)-1)+((j)-1)*(long)ldv]
    double smlnum=SAFMIN*(n/ULP);
    double xr[64], xi[64];
    double *Xr = xr, *Xi = xi;
    double bufr[1024], bufi[1024];
    if (n>64){ Xr=bufr; Xi=bufi; if(n>1024){ ((trevc_t)orig_trevc)(side,howmny,select,N,t,LDT,vl,LDVL,vr,LDVR,MM,M,work,info,l1,l2); return; } }
    int ki=n;
    while (ki>=1){
        int ip = (ki>1 && T_(ki,ki-1)!=0) ? 1 : 0;
        double wr_=T_(ki,ki), wi_=0;
        if (ip) wi_=sqrt(fabs(T_(ki,ki-1)))*sqrt(fabs(T_(ki-1,ki)));
        double smin=fmax(ULP*(fabs(wr_)+fabs(wi_)),smlnum);
        int top;
        if (!ip){
            Xr[ki-1]=1; Xi[ki-1]=0;
            for (int k=1;k<ki;k++){ Xr[k-1]=-T_(k,ki); Xi[k-1]=0; }
            top=ki-1;
        } else {
            double ar, bi;
            if (fabs(T_(ki-1,ki))>=fabs(T_(ki,ki-1))){ ar=1; bi=wi_/T_(ki-1,ki); Xr[ki-2]=1; Xi[ki-2]=0; Xr[ki-1]=0; Xi[ki-1]=bi; }
            else { ar=-wi_/T_(ki,ki-1); bi=1; Xr[ki-2]=ar; Xi[ki-2]=0; Xr[ki-1]=0; Xi[ki-1]=1; }
            for (int k=1;k<=ki-2;k++){ Xr[k-1]=-Xr[ki-2]*T_(k,ki-1); Xi[k-1]=-Xi[ki-1]*T_(k,ki); }
            top=ki-2;
        }
        int j=top;
        while (j>=1){
            if (j>1 && T_(j,j-1)!=0){
                /* 2x2 block rows j-1,j */
                double a11=T_(j-1,j-1)-wr_, a12=T_(j-1,j), a21=T_(j,j-1), a22=T_(j,j)-wr_;
                /* complex matrix: [a11 - i wi, a12; a21, a22 - i wi] */
                double m11r=a11, m11i=-wi_, m22r=a22, m22i=-wi_;
                double detr = m11r*m22r - m11i*m22i - a12*a21;
                double deti = m11r*m22i + m11i*m22r;
                double dabs = fabs(detr)+fabs(deti);
                double nrm = fabs(m11r)+fabs(m11i)+fabs(a12)+fabs(a21)+fabs(m22r)+fabs(m22i);
                if (dabs < smin*fmax(nrm, smin)){ detr = smin*fmax(nrm,smin); deti=0; }
                double b1r=Xr[j-2], b1i=Xi[j-2], b2r=Xr[j-1], b2i=Xi[j-1];
                /* x1 = (m22*b1 - a12*b2)/det ; x2 = (m11*b2 - a21*b1)/det */
                double n1r = m22r*b1r - m22i*b1i - a12*b2r, n1i = m22r*b1i + m22i*b1r - a12*b2i;
                double n2r = m11r*b2r - m11i*b2i - a21*b1r, n2i = m11r*b2i + m11i*b2r - a21*b1i;
                double dd = detr*detr+deti*deti;
                double x1r=(n1r*detr+n1i*deti)/dd, x1i=(n1i*detr-n1r*deti)/dd;
                double x2r=(n2r*detr+n2i*deti)/dd, x2i=(n2i*detr-n2r*deti)/dd;
                Xr[j-2]=x1r; Xi[j-2]=x1i; Xr[j-1]=x2r; Xi[j-1]=x2i;
                for (int k=1;k<=j-2;k++){
                    Xr[k-1]-= x1r*T_(k,j-1)+x2r*T_(k,j);
                    Xi[k-1]-= x1i*T_(k,j-1)+x2i*T_(k,j);
                }
                j-=2;
            } else {
                double dr=T_(j,j)-wr_, di=-wi_;
                if (fabs(dr)+fabs(di)<smin){ dr=smin; di=0; }
                double br=Xr[j-1], bi2=Xi[j-1];
                double xr_, xi_;
                if (di==0){ xr_=br/dr; xi_=bi2/dr; }
                else { double dd=dr*dr+di*di; xr_=(br*dr+bi2*di)/dd; xi_=(bi2*dr-br*di)/dd; }
                Xr[j-1]=xr_; Xi[j-1]=xi_;
                for (int k=1;k<=j-1;k++){ Xr[k-1]-=xr_*T_(k,j); Xi[k-1]-=xi_*T_(k,j); }
                j-=1;
            }
            /* guard against growth */
            double mx=0; for (int k=j;k<ki;k++){ double a=fabs(Xr[k])+fabs(Xi[k]); if(a>mx) mx=a; }
            if (mx>1e100){ double s=1/mx; for(int k=0;k<ki;k++){ Xr[k]*=s; Xi[k]*=s; } }
        }
        if (!ip){
            double emax=0; for (int k=0;k<ki;k++) if (fabs(Xr[k])>emax) emax=fabs(Xr[k]);
            double r=1/emax;
            for (int k=1;k<=ki;k++) V_(k,ki)=Xr[k-1]*r;
            for (int k=ki+1;k<=n;k++) V_(k,ki)=0;
            ki-=1;
        } else {
            double emax=0; for (int k=0;k<ki;k++){ double a=fabs(Xr[k])+fabs(Xi[k]); if(a>emax) emax=a; }
            double r=1/emax;
            for (int k=1;k<=ki;k++){ V_(k,ki-1)=Xr[k-1]*r; V_(k,ki)=Xi[k-1]*r; }
            for (int k=ki+1;k<=n;k++){ V_(k,ki-1)=0; V_(k,ki)=0; }
            ki-=2;
        }
    }
}
