{"command": "cat > arloop3.c <<'EOF'
#include <stdint.h>
#include <pthread.h>
#include <stdatomic.h>
#include <immintrin.h>
typedef void (*naupd_t)(void*, double*, double*, int, int*, double*, double*);
#define MAXT 8
static int nthreads = 0;
static pthread_t th[MAXT];
static pthread_mutex_t mu = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t cv = PTHREAD_COND_INITIALIZER;
static atomic_int active = 0;
static atomic_int gen = 0;
static atomic_int done = 0;
static int g_n; static const int32_t *g_ip, *g_ix; static const double *g_d, *g_x; static double* g_y;
static int bounds[MAXT+2];

static void rows(int a, int b){
    const int32_t* ip=g_ip; const int32_t* ix=g_ix; const double* d=g_d; const double* x=g_x; double* y=g_y;
    for (int i=a;i<b;i++){ double s=0.0; for (int j=ip[i]; j<ip[i+1]; j++) s+=d[j]*x[ix[j]]; y[i]=s; }
}
static void* worker(void* arg){
    int id=(int)(intptr_t)arg;
    int seen=atomic_load(&gen);
    for(;;){
        if (!atomic_load_explicit(&active, memory_order_acquire)){
            pthread_mutex_lock(&mu);
            while(!atomic_load(&active)) pthread_cond_wait(&cv,&mu);
            pthread_mutex_unlock(&mu);
            seen=atomic_load(&gen);
            continue;
        }
        int g=atomic_load_explicit(&gen, memory_order_acquire);
        if (g!=seen){
            seen=g;
            rows(bounds[id], bounds[id+1]);
            atomic_fetch_add_explicit(&done,1,memory_order_release);
        } else _mm_pause();
    }
    return 0;
}
int init(int nt){
    if (nthreads) return nthreads;
    if (nt>MAXT) nt=MAXT;
    for (int i=1;i<nt;i++) pthread_create(&th[i],0,worker,(void*)(intptr_t)i);
    nthreads=nt; return nt;
}
static void par_mv(int n){
    int nt=nthreads;
    atomic_store_explicit(&done,0,memory_order_relaxed);
    atomic_fetch_add_explicit(&gen,1,memory_order_release);
    rows(bounds[0],bounds[1]);
    while (atomic_load_explicit(&done,memory_order_acquire)!=nt-1) _mm_pause();
}
int run(void* fn, void* st, double* resid, double* v, int n, int* ipntr, double* workd, double* workl,
        const int32_t* indptr, const int32_t* indices, const double* data) {
    naupd_t f = (naupd_t)fn;
    int* ido = (int*)((char*)st + 0x34);
    int nt = nthreads>0?nthreads:1;
    g_n=n; g_ip=indptr; g_ix=indices; g_d=data;
    /* balance by nnz */
    int64_t nnz=indptr[n]; bounds[0]=0; int r=0;
    for (int t=1;t<nt;t++){ int64_t target=nnz*t/nt; while(r<n && indptr[r]<target) r++; bounds[t]=r; }
    bounds[nt]=n;
    int par = (nt>1 && nnz>=2000);
    if (par){ pthread_mutex_lock(&mu); atomic_store(&active,1); pthread_cond_broadcast(&cv); pthread_mutex_unlock(&mu); }
    int c;
    for (;;) {
        f(st, resid, v, n, ipntr, workd, workl);
        for (int q = 0xc0; q < 0x400; q++) ((char*)st)[q] = 0;
        c = *ido;
        if (c == 1 || c == 5) {
            g_x = workd + ipntr[0]; g_y = workd + ipntr[1];
            if (par) par_mv(n); else { bounds[0]=0; int b1=bounds[1]; bounds[1]=n; rows(0,n); bounds[1]=b1; }
        } else if (c == 2) {
            const double* x = workd + ipntr[0];
            double* y = workd + ipntr[1];
            for (int i = 0; i < n; i++) y[i] = x[i];
        } else break;
    }
    if (par) atomic_store(&active,0);
    return c;
}
